// Calcule l'outcome a posteriori pour chaque ligne memory_decisions où outcome est vide.
// Règles :
//   - decision != 'approved' → skip (rejected/snoozed/abandoned ne sont pas observés ici)
//   - ts < 7 jours → skip (laisser le temps de voir un signal)
//   - prospect : reply_category=interested|needs_quote → reply_received
//                reply_category=not_interested|opt_out  → rejected_by_prospect
//                pas de reply_received_at + > 30j depuis ts → no_reply
//   - project  : status=delivered → delivered
//                status=abandoned → abandoned
//                status=blocked + bloqué > 30j → stuck
//   - autres item_type (finance_light, follow_up, ops...) : skip pour l'instant.
const now = Date.now();
const SEVEN_D = 7 * 86400 * 1000;
const THIRTY_D = 30 * 86400 * 1000;
const MAX_BATCH = 50; // anti-flood : limite par run.
const memDec = $('Read memory_decisions').all().map(i => i.json);
const review = $('Read review_queue').all().map(i => i.json);
const projects = $('Read project_queue').all().map(i => i.json);
const reviewById = Object.fromEntries(review.map(r => [String(r.id), r]));
const projectById = Object.fromEntries(projects.map(p => [String(p.id), p]));
const lower = v => String(v||'').toLowerCase();
const out = [];
const skipped = { not_approved: 0, too_recent: 0, already_set: 0, no_match: 0, undecided_yet: 0, unsupported_type: 0 };
for (const d of memDec) {
  if (d.outcome && String(d.outcome).trim()) { skipped.already_set++; continue; }
  if (lower(d.decision) !== 'approved') { skipped.not_approved++; continue; }
  const ts = Date.parse(d.ts || ''); if (!Number.isFinite(ts)) continue;
  if ((now - ts) < SEVEN_D) { skipped.too_recent++; continue; }
  const item_type = lower(d.item_type);
  let outcome = '';
  if (item_type === 'prospect') {
    const r = reviewById[String(d.item_id)];
    if (!r) { skipped.no_match++; continue; }
    const cat = lower(r.reply_category);
    if (cat === 'interested' || cat === 'needs_quote') outcome = 'reply_received';
    else if (cat === 'not_interested' || lower(r.reply_opt_out) === 'true') outcome = 'rejected_by_prospect';
    else if ((now - ts) >= THIRTY_D) outcome = 'no_reply';
    else { skipped.undecided_yet++; continue; }
  } else if (item_type === 'project') {
    const p = projectById[String(d.item_id)];
    if (!p) { skipped.no_match++; continue; }
    const st = lower(p.status);
    if (st === 'delivered') outcome = 'delivered';
    else if (st === 'abandoned') outcome = 'abandoned';
    else if (st === 'blocked' && (now - ts) >= THIRTY_D) outcome = 'stuck';
    else { skipped.undecided_yet++; continue; }
  } else {
    skipped.unsupported_type++; continue;
  }
  if (!outcome) continue;
  out.push({ json: { id: d.id, outcome, outcome_observed_at: new Date().toISOString() } });
  if (out.length >= MAX_BATCH) break;
}
// Append un item de stats en plus pour le log final (filtré ensuite).
out.push({ json: { _stats: true, computed: out.length, ...skipped } });
return out;
